contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address recipient, uint256 fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fund, "insufficient balance");

        uint256 beforeBal = address(c).balance;

        bool reverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted
                ? address(c).balance == beforeBal
                : address(c).balance + 100 == beforeBal
        );
    }
}

